import 'jest';
import { stringInterpolate } from '../../src';

describe('stringInterpolate()', () => {
    test('should replace placeholders with values from and object', () => {
        const input = 'Hi, my name is ${name} and I am ${age} years old';
        const output = 'Hi, my name is Shep and I am 21 years old';
        expect(stringInterpolate(input, { name: 'Shep', age: 21 })).toEqual(output);
    });
});